今天哥们又接到一个文件处理的开发需求，要实现一个文件上传、下载的通用服务。为了快速满足这一需求，我使用了SpringBoot + 华为云OBS快速写了一个小小的程序。
项目结构如下:
src└── main    ├── java    │   └── com    │       └── xmbc    │           └── file    │               ├── XmbcFileApplication.java # 启动类    │               ├── config    │               │   ├── HuaweiObsConfig.java # 华为云OBS的配置 （1）    │               │   └── ResourcesConfig.java      │               ├── controller     │               │   ├── HuaweiObsFileController.java # 文件上传下载的Controller （4）    │               │   └── SysFileController.java    │               ├── service    │               │   ├── ISysFileService.java # 文件处理的接口 （2）    │               │   └── impl    │               │       ├── FastDfsSysFileServiceImpl.java    │               │       ├── HuaweiObsSysFileServiceImpl.java # 华为云OBS的实现 （3）    │               │       └── LocalSysFileServiceImpl.java    │               └── utils    │                   └── FileUploadUtils.java    └── resources        ├── application-dev.yaml  # 若依的框架原配置，没啥用，当个备份吧        ├── application-local.yaml # 本地配置        ├── banner.txt # 默认的logo        ├── bootstrap.yaml # 启动类        └── logback.xml # 日志配置12 directories, 15 files

好吧，大佬一看就知道这是使用了某个开源的框架，本文使用了若依的框架(对应ruoyi-file)。因为本文作者是个程序菜鸟，为了快速满足开发组长的需求，所以使用起来比较粗糙。  
首先，看看我做了什么好事。在bootstrap.yaml和application-local.yaml中配置好参数，如下:
# bootstrap.yamlspring:  profiles:    active: local# application-local.yamlserver:  port: 9300spring:  profiles:    activate:      on-profile: local  application:    name: xmbc-file  cloud:    nacos:      discovery:        enabled: false # 禁用nacosobs:  huawei:    bucketName: test-xcmg-app-fileprocessing # 华为云OBS的bucket名称    endPoint: https://obs.cn-east-3.myhuaweicloud.com # 华为云OBS的endpointfile: # 先随便乱写的，为了保证config可以读取，这里随便写一个。后续有需要再修改  path: &quot;/&quot;   prefix: &quot;xmbc_file&quot;   domain: &quot;local.xmbc.com&quot;

启动配置完成之后，我们就根据我上文的目录结构后注释的编号来看看对应的代码：
(1) HuaweiObsConfig.javapackage com.xmbc.file.config;import com.obs.services.ObsClient;import lombok.Data;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.context.properties.ConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;/** * Minio 配置信息 * * @author xmbc */@Configuration@ConfigurationProperties(prefix = &quot;obs&quot;)@Datapublic class HuaweiObsConfig&#123;    /**     * endpoint填写桶所在的endpoint     */    @Value(&quot;$&#123;obs.huawei.endPoint&#125;&quot;)    String endPoint;    /**     * 华为云Access Key     */    private String accessKey = System.getenv(&quot;HUAWEICLOUD_SDK_AK&quot;);     /**     * 华为云Secret Key     */    private String secretKey = System.getenv(&quot;HUAWEICLOUD_SDK_SK&quot;);    /**     * 存储桶名称     */    @Value(&quot;$&#123;obs.huawei.bucketName&#125;&quot;)    private String bucketName;    /**     * 创建ObsClient实例     * 使用永久AK/SK初始化客户端     */    @Bean    public ObsClient getHuaweiObsClient()    &#123;        return new ObsClient(accessKey, secretKey,endPoint);    &#125;&#125;

(2) ISysFileService.javapackage com.xmbc.file.service;import org.springframework.core.io.InputStreamResource;import org.springframework.web.multipart.MultipartFile;/** * 文件接口 *  * @author xmbc */public interface ISysFileService&#123;    /**     * 文件上传接口     *      * @param file 上传的文件     * @return 访问地址     * @throws Exception     */    public String uploadFile(MultipartFile file) throws Exception;    /**     * 文件下载接口     *     * @param fileName 下载的文件     * @return 访问地址     * @throws Exception     */    public InputStreamResource downloadFile(String fileName) throws Exception;&#125;

(3) HuaweiObsSysFileServiceImpl.javapackage com.xmbc.file.service.impl;import com.alibaba.nacos.common.utils.IoUtils;import com.obs.services.ObsClient;import com.obs.services.model.PutObjectRequest;import com.obs.services.model.PutObjectResult;import com.xmbc.file.config.HuaweiObsConfig;import com.xmbc.file.service.ISysFileService;import com.xmbc.file.utils.FileUploadUtils;import io.minio.MinioClient;import io.minio.PutObjectArgs;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.core.io.InputStreamResource;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import java.io.InputStream;/** *文件存储 * * @author xmbc */@Service(value = &quot;huaweiObsSysFileService&quot;)public class HuaweiObsSysFileServiceImpl implements ISysFileService&#123;    @Autowired    private HuaweiObsConfig huaweiObsConfig;    @Autowired    private ObsClient huaweiObsClient;    /**     * Minio文件上传接口     *     * @param file 上传的文件     * @return 访问地址     * @throws Exception     */    @Override    public String uploadFile(MultipartFile file) throws Exception    &#123;        String fileName = FileUploadUtils.extractFilename(file);        InputStream inputStream = file.getInputStream();        PutObjectRequest request = new PutObjectRequest();        request.setBucketName(huaweiObsConfig.getBucketName());        request.setObjectKey(fileName);        request.setInput(inputStream);        PutObjectResult putObjectResult = huaweiObsClient.putObject(request);        IoUtils.closeQuietly(inputStream);        return putObjectResult.getObjectUrl();    &#125;    @Override    public InputStreamResource downloadFile(String fileName) throws Exception &#123;        return new InputStreamResource(huaweiObsClient.getObject(huaweiObsConfig.getBucketName(), fileName).getObjectContent());    &#125;&#125;

(4) HuaweiObsController.javapackage com.xmbc.file.controller;import com.xmbc.common.core.domain.R;import com.xmbc.common.core.utils.file.FileUtils;import com.xmbc.file.service.ISysFileService;import com.xmbc.system.api.domain.SysFile;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.core.io.InputStreamResource;import org.springframework.http.HttpHeaders;import org.springframework.http.MediaType;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.util.Optional;/** * 文件请求处理 *  * @author xmbc */@RestControllerpublic class HuaweiObsFileController &#123;    private static final Logger log = LoggerFactory.getLogger(HuaweiObsFileController.class);    @Autowired    @Qualifier(&quot;huaweiObsSysFileService&quot;)    private ISysFileService huaweiObsSysFileService;    /**     * 上传对象文件     * @param multipartFile     * @return     * @throws IOException     */    @RequestMapping(value = &quot;/uploadObject&quot;, method = &#123;RequestMethod.POST, RequestMethod.PUT&#125; , produces = MediaType.APPLICATION_JSON_VALUE)    public R&lt;SysFile&gt; uploadObject(@RequestParam(&quot;file&quot;) MultipartFile multipartFile) throws Exception &#123;        try        &#123;            // 上传并返回访问地址            String url = huaweiObsSysFileService.uploadFile(multipartFile);            SysFile sysFile = new SysFile();            sysFile.setName(FileUtils.getName(url));            sysFile.setUrl(url);            return R.ok(sysFile);        &#125;        catch (Exception e)        &#123;            log.error(&quot;上传文件失败&quot;, e);            return R.fail(&quot;上传文件失败: &quot; + e.getMessage());        &#125;    &#125;    /**     * 下载对象文件     * @param fileName 文件名     * @return 文件对象     * @throws IOException     */    @RequestMapping(value = &quot;/downloadObject&quot;, method = &#123;RequestMethod.GET&#125; , produces = MediaType.APPLICATION_JSON_VALUE)    public ResponseEntity downloadObject(@RequestParam(&quot;fileName&quot;) String fileName, @RequestParam(value = &quot;openStyle&quot;,required = false) String openStyle) throws Exception &#123;        try        &#123;            openStyle= &quot;inline&quot;.equals(openStyle)?&quot;inline&quot;:&quot;attachment&quot;;            HttpHeaders headers = new HttpHeaders();            InputStreamResource inputStreamResource = huaweiObsSysFileService.downloadFile(fileName);            headers.add(HttpHeaders.CONTENT_DISPOSITION, openStyle + &quot;; filename=&quot; + fileName.substring(fileName.lastIndexOf(&#x27;/&#x27;)+1));            return ResponseEntity.ok()                    .headers(headers)                    .body(inputStreamResource);        &#125;        catch (Exception e)        &#123;            log.error(&quot;下载文件失败&quot;, e);            return ResponseEntity.of(Optional.of(e.getMessage()));        &#125;    &#125;&#125;

1. 简单1.1 两数之和给定一个整数数组 nums 和一个整数目标值 target，请你在该数组中找出 和为目标值 target  的那 两个 整数，并返回它们的数组下标。
你可以假设每种输入只会对应一个答案，并且你不能使用两次相同的元素。
你可以按任意顺序返回答案。
示例 1：输入：nums = [2,7,11,15], target = 9输出：[0,1]解释：因为 nums[0] + nums[1] == 9 ，返回 [0, 1] 。示例 2：输入：nums = [3,2,4], target = 6输出：[1,2]示例 3：输入：nums = [3,3], target = 6输出：[0,1] 提示：2 &lt;= nums.length &lt;= 104-109 &lt;= nums[i] &lt;= 109-109 &lt;= target &lt;= 109只会存在一个有效答案 进阶：你可以想出一个时间复杂度小于 O(n2) 的算法吗？


// O(n^2)//按照距离寻找//相邻, 间隔一位, 间隔二位, 间隔三位....//01, 12,23,34,45,56....//02, 13, 24, 35....class Solution &#123;    public int[] twoSum(int[] nums, int target) &#123;        for(int i = 1; i &lt; nums.length; i++)&#123;            for(int j = i; j &lt; nums.length; j++)&#123;                if(nums[j-i] + nums[j] == target)&#123;                    return new int[]&#123;j-i, j&#125;;                &#125;            &#125;        &#125;        return new int[]&#123;0,0&#125;;    &#125;&#125;//哈希表//注意到方法一的时间复杂度较高的原因是寻找 target - x 的时间复杂度过高。因此，我们需要一种更优秀的方法，能够快速寻找数组中是否存在目标元素。如果存在，我们需要找出它的索引。// 使用哈希表，可以将寻找 target - x 的时间复杂度降低到从 O(N) 降低到 O(1)。// 这样我们创建一个哈希表，对于每一个 x，我们首先查询哈希表中是否存在 target - x，然后将 x 插入到哈希表中，即可保证不会让 x 和自己匹配。// 时间复杂度：O(N)，其中 N 是数组中的元素数量。对于每一个元素 x，我们可以 O(1) 地寻找 target - x。// 空间复杂度：O(N)，其中 N 是数组中的元素数量。主要为哈希表的开销。class Solution &#123;    public int[] twoSum(int[] nums, int target) &#123;    Map&lt;Integer, Integer&gt; map = new HashMap&lt;&gt;();    for (int i = 0; i &lt; nums.length; i++) &#123;        int complement = target - nums[i]; // 寻找 target - x        if (map.containsKey(complement)) &#123; // 如果存在，返回索引            return new int[] &#123; map.get(complement), i &#125;;        &#125;        map.put(nums[i], i); // 将 x 插入哈希表    &#125;    throw new IllegalArgumentException(&quot;No two sum solution&quot;);&#125;&#125;

1.2 两数相加给你两个 非空 的链表，表示两个非负的整数。它们每位数字都是按照 逆序 的方式存储的，并且每个节点只能存储 一位 数字。
请你将两个数相加，并以相同形式返回一个表示和的链表。
你可以假设除了数字 0 之外，这两个数都不会以 0 开头。
示例 1：输入：l1 = [2,4,3], l2 = [5,6,4]输出：[7,0,8]解释：342 + 465 = 807.示例 2：输入：l1 = [0], l2 = [0]输出：[0]示例 3：输入：l1 = [9,9,9,9,9,9,9], l2 = [9,9,9,9]输出：[8,9,9,9,0,0,0,1]
class Solution &#123;    public ListNode addTwoNumbers(ListNode l1, ListNode l2) &#123;        ListNode head = null, tail = null;        int carry = 0;        while (l1 != null || l2 != null) &#123;            int n1 = l1 != null ? l1.val : 0;            int n2 = l2 != null ? l2.val : 0;            int sum = n1 + n2 + carry;            if (head == null) &#123;                head = tail = new ListNode(sum % 10);            &#125; else &#123;                tail.next = new ListNode(sum % 10);                tail = tail.next;            &#125;            carry = sum / 10;            if (l1 != null) &#123;                l1 = l1.next;            &#125;            if (l2 != null) &#123;                l2 = l2.next;            &#125;        &#125;        if (carry &gt; 0) &#123;            tail.next = new ListNode(carry);        &#125;        return head;    &#125;&#125;

1.3 无重复字符的最长子串给定一个字符串 s ，请你找出其中不含有重复字符的 最长”子串”的长度。
示例 1:输入: s = &quot;abcabcbb&quot;输出: 3 解释: 因为无重复字符的最长子串是 &quot;abc&quot;，所以其长度为 3。示例 2:输入: s = &quot;bbbbb&quot;输出: 1解释: 因为无重复字符的最长子串是 &quot;b&quot;，所以其长度为 1。示例 3:输入: s = &quot;pwwkew&quot;输出: 3解释: 因为无重复字符的最长子串是 &quot;wke&quot;，所以其长度为 3。     请注意，你的答案必须是 子串 的长度，&quot;pwke&quot; 是一个子序列，不是子串。提示：0 &lt;= s.length &lt;= 5 * 104s 由英文字母、数字、符号和空格组成

//滑动窗口class Solution &#123;    public int lengthOfLongestSubstring(String s) &#123;        int n = s.length();        if(n&lt;=1)&#123;            return n;        &#125;        int l = 0, r = 1;        HashSet&lt;Character&gt; set = new HashSet&lt;&gt;();        set.add(s.charAt(l));        int res = 0;        while(r&lt;n)&#123;            while(r&lt;n &amp;&amp; !set.contains(s.charAt(r)))&#123;                set.add(s.charAt(r));                r++;            &#125;            res = Math.max(res, r-l);            set.remove(s.charAt(l)); //             l++;        &#125;        return res;    &#125;&#125;

