创建实体类, 创建set和get方法, 载属性上使用注解实现校验规则
常用的注解 package com.learning.spring6.validator.two;import jakarta.validation.constraints.Max;import jakarta.validation.constraints.Min;import jakarta.validation.constraints.NotNull;/** * @Author fei * @Version 1.0 * @Description TODO * @DATA 2024/11/21 16:21 */public class User &#123; @NotNull private String name; @Min(value = 0, message = &quot;不小于0&quot;) @Max(value = 200,message = &quot;不大于200&quot;) private int age; public int getAge() &#123; return age; &#125; public void setAge(int age) &#123; this.age = age; &#125; public String getName() &#123; return name; &#125; public void setName(String name) &#123; this.name = name; &#125;&#125;
创建校验器
1 使用jakarta包的validator package com.learning.spring6.validator.two;import jakarta.validation.ConstraintViolation;import jakarta.validation.Validator;import jakarta.validation.groups.Default;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import java.util.Set;/** * @Author fei * @Version 1.0 * @Description TODO * @DATA 2024/11/21 16:26 */@Servicepublic class MyValidator1 &#123; @Autowired private Validator validator; public boolean validate1(User user) &#123; Set&lt;ConstraintViolation&lt;User&gt;&gt; validate = validator.validate(user); return validate.isEmpty(); &#125;&#125;
2 使用spring框架的validator package com.learning.spring6.validator.two;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import org.springframework.validation.BindException;import org.springframework.validation.Validator;/** * @Author fei * @Version 1.0 * @Description TODO * @DATA 2024/11/21 16:28 */@Componentpublic class MyValidator2 &#123; @Autowired private Validator validator; public boolean validate2(User user)&#123; BindException bindException = new BindException(user, user.getName()); validator.validate(user, bindException); return bindException.hasErrors(); &#125;&#125;
