package com.learning.spring6.validator.by_selfdefine;import jakarta.validation.Constraint;import jakarta.validation.Payload;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.NotNull;import java.lang.annotation.*;/** * @Author fei * @Version 1.0 * @Description TODO * @DATA 2024/11/21 17:17 */@Target(&#123;ElementType.FIELD&#125;)@Retention(RetentionPolicy.RUNTIME)@Documented//@Repeatable(CannotBlank.List.class)@Constraint(validatedBy = CannotBlankValidator.class)public @interface CannotBlank &#123; //默认提示信息 String message() default &quot;不能包含空格&quot;; Class&lt;?&gt;[] groups() default &#123;&#125;; Class&lt;? extends Payload&gt;[] payload() default &#123;&#125;; @Target(&#123;ElementType.METHOD, ElementType.FIELD, ElementType.ANNOTATION_TYPE, ElementType.CONSTRUCTOR, ElementType.PARAMETER, ElementType.TYPE_USE&#125;) @Retention(RetentionPolicy.RUNTIME) @Documented public @interface List &#123; CannotBlank[] value(); &#125;&#125; package com.learning.spring6.validator.by_selfdefine;import jakarta.validation.ConstraintValidator;import jakarta.validation.ConstraintValidatorContext;/** * @Author fei * @Version 1.0 * @Description TODO * @DATA 2024/11/21 17:19 */public class CannotBlankValidator implements ConstraintValidator&lt;CannotBlank, String&gt; &#123; @Override public boolean isValid(String value, ConstraintValidatorContext context) &#123; if(value != null &amp;&amp; value.contains(&quot; &quot;)) &#123; return false; &#125; return true; &#125;&#125;
定义实体类 package com.learning.spring6.validator.by_selfdefine;/** * @Author fei * @Version 1.0 * @Description TODO * @DATA 2024/11/21 17:34 */public class User &#123; @CannotBlank private String name; private int age; public int getAge() &#123; return age; &#125; public void setAge(int age) &#123; this.age = age; &#125; public String getName() &#123; return name; &#125; public void setName(String name) &#123; this.name = name; &#125;&#125;
