5.4 数据持久化- 本地文件
repository

package com.learning.langchain4j.repository;import dev.langchain4j.data.message.ChatMessage;import dev.langchain4j.data.message.ChatMessageDeserializer;import dev.langchain4j.data.message.ChatMessageSerializer;import dev.langchain4j.store.memory.chat.ChatMemoryStore;import org.springframework.stereotype.Repository;import java.io.*;import java.nio.file.Path;import java.nio.file.Paths;import java.util.HashMap;import java.util.List;import java.util.Map;@Repositorypublic class MyChatMemoryStore implements ChatMemoryStore &#123;    // 存储路径：优先使用resource目录下的memory文件    private static final Path STORAGE_PATH = Paths.get(&quot;src/main/resources/memory&quot;);    private final Map&lt;Object, String&gt; memoryMap = new HashMap&lt;&gt;();    public MyChatMemoryStore() &#123;        loadFromFile(); // 初始化时加载持久化数据    &#125;    // 从文件加载会话记忆    private synchronized void loadFromFile() &#123;        try (ObjectInputStream ois = new ObjectInputStream(                new FileInputStream(STORAGE_PATH.toFile()))) &#123;            Map&lt;Object, String&gt; loadedMap = (Map&lt;Object, String&gt;) ois.readObject();            memoryMap.putAll(loadedMap);        &#125; catch (FileNotFoundException e) &#123;            initStorageFile(); // 首次使用时创建文件        &#125; catch (IOException | ClassNotFoundException e) &#123;            throw new RuntimeException(&quot;Failed to load chat memory&quot;, e);        &#125;    &#125;    // 初始化存储文件    private void initStorageFile() &#123;        try &#123;            File file = STORAGE_PATH.toFile();            if (!file.getParentFile().exists()) &#123;                file.getParentFile().mkdirs();            &#125;            file.createNewFile();            saveToFile(); // 创建空文件        &#125; catch (IOException e) &#123;            throw new RuntimeException(&quot;Failed to initialize storage file&quot;, e);        &#125;    &#125;    // 保存会话记忆到文件    private synchronized void saveToFile() &#123;        try (ObjectOutputStream oos = new ObjectOutputStream(                new FileOutputStream(STORAGE_PATH.toFile()))) &#123;            oos.writeObject(memoryMap);        &#125; catch (IOException e) &#123;            throw new RuntimeException(&quot;Failed to save chat memory&quot;, e);        &#125;    &#125;    @Override    public List&lt;ChatMessage&gt; getMessages(Object memoryId) &#123;        String s = memoryMap.get(memoryId);        List&lt;ChatMessage&gt; list = ChatMessageDeserializer.messagesFromJson(s);        return list;    &#125;    @Override    public void updateMessages(Object memoryId, List&lt;ChatMessage&gt; messages) &#123;        String s = ChatMessageSerializer.messagesToJson(messages);        memoryMap.put(memoryId, s);        saveToFile(); // 更新后立即持久化    &#125;    @Override    public void deleteMessages(Object memoryId) &#123;        memoryMap.remove(memoryId);        saveToFile(); // 删除后立即持久化    &#125;&#125;




config

@Beanpublic ChatMemoryProvider chatMemoryProvider(OllamaConfigProperties ollamaConfigProperties,ChatMemoryStore myChatMemoryStore)&#123;    return new ChatMemoryProvider()&#123;        @Override        public ChatMemory get(Object o) &#123;            return MessageWindowChatMemory.builder()                    .id(o)                    .maxMessages(ollamaConfigProperties.getMaxMessages())                    .chatMemoryStore(myChatMemoryStore)                    .build();        &#125;    &#125;;&#125;



6. RAG知识库6.1 原理
知识文本通过向量模型转为向量
将向量和文本一一存储到向量数据库
用户输入时，先计算用户提问的文本对应的向量，然后再到向量数据库中去匹配，计算用户输入向量与数据库中向量余弦相似度
设定余弦相似度阈值，例如0.5，那么余弦相似度大于0.5的数据就会被提取出来，和用户提问数据一并交给大模型处理

6.2 快速入门
引入依赖

&lt;!--RAG数据库相关依赖--&gt;&lt;dependency&gt;    &lt;groupId&gt;dev.langchain4j&lt;/groupId&gt;    &lt;artifactId&gt;langchain4j-easy-rag&lt;/artifactId&gt;    &lt;version&gt;1.0.1-beta6&lt;/version&gt;&lt;/dependency&gt;


config

/** * 加载文件进内存，当作RAG * @return */@Beanpublic EmbeddingStore embeddingStore()&#123;  // 出现重名需要重命名    // 1.加载文件进内存，构建向量数据库操作对象    List&lt;Document&gt; contents = ClassPathDocumentLoader.loadDocuments(&quot;content&quot;);    InMemoryEmbeddingStore store = new InMemoryEmbeddingStore();  // 使用内存当作向量数据库    // 文本切割，向量化    EmbeddingStoreIngestor ingestor = EmbeddingStoreIngestor.builder()            .embeddingStore(store)            .build();    IngestionResult ingest = ingestor.ingest(contents);    return store;&#125;//构建向量数据库检索对象@Beanpublic ContentRetriever contentRetriever(EmbeddingStore embeddingStore)&#123;    return EmbeddingStoreContentRetriever.builder()            .embeddingStore(embeddingStore)            .minScore(0.5)            .maxResults(3)            .build();&#125;


