@Componentpublic class ReservationTool &#123;    @Autowired    private ReservationService reservationService;    // 1. 工具：添加预约信息    @Tool(&quot;预约志愿填报服务&quot;)    public void addReservation(        @P(&quot;考生姓名&quot;) String name,        @P(&quot;考生性别&quot;) String gender,        @P(&quot;考生电话&quot;) String phone,        @P(&quot;会话时间&quot;) LocalDateTime communicationTime,        @P(&quot;考生所在省份&quot;) String province,        @P(&quot;考生预估分数&quot;) Integer estimateScore    ) &#123;        Reservation build = Reservation.builder()                .id(null)                .name(name)                .gender(gender)                .phone(phone)                .communicationTime(communicationTime)                .province(province)                .estimateScore(estimateScore)                .build();        reservationService.insert(build);    &#125;    // 2. 工具： 查询预约信息    @Tool(&quot;根据用户手机号码查询预约单&quot;)    public Reservation findReservation(@P(&quot;考生电话&quot;) String phone)&#123;        return reservationService.findByPhone(phone);    &#125;&#125;


