/** * 处理sql异常 * @param ex * @return */ @ExceptionHandler public Result exceptionHandler(SQLIntegrityConstraintViolationException ex)&#123; //Duplicate entry &#x27;lisi&#x27; for key &#x27;employee.idx_username&#x27; String message = ex.getMessage(); if(message.contains(&quot;Duplicate entry&quot;))&#123; String[] s = message.split(&quot; &quot;); String username = s[2]; String msg = username + MessageConstant.ALREADY_EXISTS; return Result.error(msg); &#125;else &#123; return Result.error(MessageConstant.UNKNOWN_ERROR); &#125; &#125;
