jwt原理
可以通过JWT令牌解析出当前用户的id，在interceptor解析的id传递到Service的save方法 使用ThreadLocal进行id值的传递
ThreadLocal并不是一个Thread，而是Thread的局部变量 ThreadLocal为每一个线程提供单独一份的存储空间，具有线程隔离的效果，只有在线程内才能获取到对应的值，线程外则不能访问 ThreadLocal常用的方法：
public void set(T value) public T get() public void remove()
// 1. 自定义Thread类package com.sky.context;public class BaseContext &#123; public static ThreadLocal&lt;Long&gt; threadLocal = new ThreadLocal&lt;&gt;(); public static void setCurrentId(Long id) &#123; threadLocal.set(id); &#125; public static Long getCurrentId() &#123; return threadLocal.get(); &#125; public static void removeCurrentId() &#123; threadLocal.remove(); &#125;&#125;// 2. 在interceptor中添加id //1、从请求头中获取令牌 String token = request.getHeader(jwtProperties.getAdminTokenName()); //2、校验令牌 try &#123; log.info(&quot;jwt校验:&#123;&#125;&quot;, token); Claims claims = JwtUtil.parseJWT(jwtProperties.getAdminSecretKey(), token); Long empId = Long.valueOf(claims.get(JwtClaimsConstant.EMP_ID).toString()); log.info(&quot;当前员工id：&quot;, empId); BaseContext.setCurrentId(empId); // 添加id到ThreadLocal //3、通过，放行 return true; &#125; catch (Exception ex) &#123; //4、不通过，响应401状态码 response.setStatus(401); return false; &#125;// 3. 在service层取出id employee.setCreateUser(BaseContext.getCurrentId()); employee.setUpdateUser(BaseContext.getCurrentId());
