package com.sky.vo;import io.swagger.annotations.ApiModel;import lombok.AllArgsConstructor;import lombok.Builder;import lombok.Data;import lombok.NoArgsConstructor;import java.io.Serializable;import java.time.LocalDateTime;@Data@Builder@NoArgsConstructor@AllArgsConstructor@ApiModel(description = &quot;员工回显数据格式&quot;)public class EmployeeVO implements Serializable &#123; private Long id; private String username; private String name; private String phone; private String sex; private String idNumber;&#125;
