2.5.2 代码导入3. 菜品管理3.1 公共字段自动填充3.1.1 问题分析对于公共字段的赋值，存在许多冗余代码。后期对其修改维护，会有大量重复操作，不太方便。
3.1.2 实现思路 3.1.3 代码开发 自定义OperationType枚举类： 只有UPDATE和INSERT操作是因为对于公共字段而言，查询和删除操作基本不存在冗余。
package com.sky.enumeration;/** * 数据库操作类型 */public enum OperationType &#123; /** * 更新操作 */ UPDATE, /** * 插入操作 */ INSERT&#125;
自定义注解AutoFile
package com.sky.annotation;import com.sky.enumeration.OperationType;import java.lang.annotation.ElementType;import java.lang.annotation.Retention;import java.lang.annotation.RetentionPolicy;import java.lang.annotation.Target;/** * 自定义注解，用于标识某个方法需要进行功能字段自动填充处理 * */@Target(ElementType.METHOD)@Retention(RetentionPolicy.RUNTIME)public @interface AutoFill &#123; //指定当前对数据库操作的操作类型 UPDATE INSERT OperationType value();&#125;
编写Aspect
package com.sky.aspect;import com.sky.annotation.AutoFill;import com.sky.constant.AutoFillConstant;import com.sky.context.BaseContext;import com.sky.enumeration.OperationType;import lombok.extern.slf4j.Slf4j;import org.aspectj.lang.JoinPoint;import org.aspectj.lang.Signature;import org.aspectj.lang.annotation.Aspect;import org.aspectj.lang.annotation.Before;import org.aspectj.lang.annotation.Pointcut;import org.aspectj.lang.reflect.MemberSignature;import org.aspectj.lang.reflect.MethodSignature;import org.springframework.stereotype.Component;import java.lang.reflect.Method;import java.time.LocalDateTime;/** * 自定义切面类：实现公共字段自动填充处理逻辑 */@Aspect@Component@Slf4jpublic class AutoFillAspect &#123; /** * 切入点：对哪些类的哪些方法进行切入 */ @Pointcut(&quot;execution(* com.sky.mapper.*.*(..)) &amp;&amp; @annotation(com.sky.annotation.AutoFill)&quot;) public void autoFillPointCut()&#123; //前置通知，在执行这些添加了AutoFill注解的方法执行之前进行公共字段的赋值 &#125; @Before(&quot;autoFillPointCut()&quot;) public void autoFill(JoinPoint joinPoint)&#123; log.info(&quot;开始进行公共字段的填充...&quot;); //1. 获取到当前被拦截的方法上的数据库操作类型 MethodSignature signature = (MethodSignature) joinPoint.getSignature(); // 方法签名对象 AutoFill autoFill = signature.getMethod().getAnnotation(AutoFill.class); // 获得方法上的注解对象 OperationType operationType = autoFill.value(); // 获取数据库操作类型 //2. 获取到当前被拦截方法的参数--实体对象 Employee Category等 Object[] args = joinPoint.getArgs(); if (args == null || args.length == 0)&#123; return; &#125; Object entity = args[0]; //3. 准备赋值的数据 -- 时间和当前用户Id LocalDateTime now = LocalDateTime.now(); Long currentId = BaseContext.getCurrentId(); //4. 根据当前不同操作类型，为对应的属性通过反射进行赋值 if( operationType == OperationType.INSERT)&#123; //插入操作：为4个公共字段赋值 try &#123; Method setCreateTime = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_CREATE_TIME, LocalDateTime.class); Method setCreateUser = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_CREATE_USER, Long.class); Method setUpdateTime = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_TIME, LocalDateTime.class); Method setUpdateUser = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_USER, Long.class); //通过反射为对象属性赋值// setCreateTime.setAccessible(true); // 当set方法是public就不需要使用setAccessible(true)这个操作// setCreateUser.setAccessible(true);// setUpdateTime.setAccessible(true);// setUpdateUser.setAccessible(true); setCreateTime.invoke(entity,now); setUpdateTime.invoke(entity,now); setCreateUser.invoke(entity,currentId); setUpdateUser.invoke(entity,currentId); &#125; catch (Exception e) &#123; throw new RuntimeException(e); &#125; &#125;else if (operationType == OperationType.UPDATE)&#123; //更新操作：为2个公共字段赋值 try &#123; Method setUpdateTime = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_TIME, LocalDateTime.class); Method setUpdateUser = entity.getClass().getDeclaredMethod(AutoFillConstant.SET_UPDATE_USER, Long.class); //通过反射为对象属性赋值 setUpdateTime.invoke(entity,now); setUpdateUser.invoke(entity,currentId); &#125; catch (Exception e) &#123; throw new RuntimeException(e); &#125; &#125; &#125;&#125;
使用案例
/** * 根据主键动态修改属性 * @param employee */@AutoFill(OperationType.UPDATE)void update(Employee employee);
