package com.sky.controller.admin;import com.sky.constant.MessageConstant;import com.sky.result.Result;import com.sky.utils.AliOssUtil;import io.swagger.annotations.Api;import io.swagger.annotations.ApiOperation;import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.util.UUID;@RestController@RequestMapping(&quot;/admin/common&quot;)@Slf4j@Api(tags = &quot;通用接口&quot;)public class CommonController &#123; @Autowired private AliOssUtil aliOssUtil; @ApiOperation(&quot;文件上传&quot;) @PostMapping(&quot;/upload&quot;) public Result&lt;String&gt; upload(MultipartFile file) &#123; log.info(&quot;文件上传：&#123;&#125;&quot;, file.getOriginalFilename()); // 使用原文件名可能有重名的情况，所以使用UUID try &#123; String originalFilename = file.getOriginalFilename(); if(originalFilename == null || originalFilename.isEmpty() )&#123; return Result.error(&quot;文件名缺失&quot;); &#125; //截取原文件名的后缀 .png .jpg String extension = originalFilename.substring(originalFilename.lastIndexOf(&quot;.&quot;) ); String objectName = UUID.randomUUID().toString() + extension; String filePath = aliOssUtil.upload(file.getBytes(), objectName); return Result.success(filePath); &#125; catch (IOException e) &#123; log.error(&quot;文件上传失败：&#123;&#125;&quot;, e.getMessage()) ; // throw new RuntimeException(e); &#125; return Result.error(MessageConstant.UPLOAD_FAILED); &#125;&#125;
