package com.sky.controller.admin;import com.sky.dto.DishDTO;import com.sky.dto.DishPageQueryDTO;import com.sky.entity.Dish;import com.sky.result.PageResult;import com.sky.result.Result;import com.sky.service.DishService;import com.sky.vo.DishVO;import io.swagger.annotations.Api;import io.swagger.annotations.ApiOperation;import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping(&quot;/admin/dish&quot;)@Api(tags = &quot;菜品相关接口&quot;)@Slf4jpublic class DishController &#123; @Autowired private DishService dishService; @PostMapping @ApiOperation(&quot;添加菜品&quot;) public Result addDish(@RequestBody DishDTO dishDTO) &#123; dishService.addDish(dishDTO); return Result.success(); &#125; @GetMapping(&quot;/page&quot;) @ApiOperation(&quot;菜品分页查询接口&quot;) public Result&lt;PageResult&gt; pageQuery(DishPageQueryDTO dishPageQueryDTO) &#123; PageResult pageResult = dishService.pageQuery(dishPageQueryDTO); return Result.success(pageResult); &#125;&#125;
