package com.sky.service.impl;import com.github.pagehelper.Page;import com.github.pagehelper.PageHelper;import com.sky.dto.DishDTO;import com.sky.dto.DishPageQueryDTO;import com.sky.entity.Dish;import com.sky.entity.DishFlavor;import com.sky.mapper.DishFlavorMapper;import com.sky.mapper.DishMapper;import com.sky.result.PageResult;import com.sky.service.DishService;import org.springframework.beans.BeanUtils;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;@Servicepublic class DishServiceImpl implements DishService &#123; @Autowired private DishMapper dishMapper; @Autowired private DishFlavorMapper dishFlavorMapper; /** * 添加菜品 * 添加菜品涉及到 菜品口味的添加，所以需要保证这个方法的原子性，因此需要使用事务注解 * @param dishDTO */ @Transactional //启动类上事务管理已开启，但是此处还需要标明此方法的事务 @Override public void addDish(DishDTO dishDTO) &#123; // 1. 向菜品表插入1条数据 Dish dish = new Dish(); BeanUtils.copyProperties(dishDTO, dish); dishMapper.insert(dish); // 2. 向菜品口味表插入n条数据 List&lt;DishFlavor&gt; flavors = dishDTO.getFlavors(); // 批量插入Flavor if (flavors != null &amp;&amp; !flavors.isEmpty()) &#123; for (DishFlavor f : flavors) &#123; f.setDishId(dish.getId()); &#125; dishFlavorMapper.insertBatch(flavors); &#125; &#125; @Override public PageResult pageQuery(DishPageQueryDTO dishPageQueryDTO) &#123; PageHelper.startPage(dishPageQueryDTO.getPage(),dishPageQueryDTO.getPageSize());// 这里会动态地将limit关键字以及后面的参数拼接到sql语句中 Page&lt;Dish&gt; page = dishMapper.pageQuery(dishPageQueryDTO); return new PageResult(page.getTotal(),page.getResult()); &#125;&#125;
