package com.sky.controller.admin;import com.sky.constant.StatusConstant;import com.sky.result.Result;import io.swagger.annotations.Api;import io.swagger.annotations.ApiOperation;import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.data.redis.core.RedisTemplate;import org.springframework.web.bind.annotation.*;@RestController(&quot;adminShopController&quot;)@RequestMapping(&quot;/admin/shop&quot;)@Slf4j@Api(tags = &quot;店铺相关接口&quot;)public class ShopController &#123; @Autowired private RedisTemplate redisTemplate; @PutMapping(&quot;/&#123;status&#125;&quot;) @ApiOperation(&quot;设置店铺营业状态&quot;) public Result setStatus(@PathVariable Integer status)&#123; log.info(&quot;设置店铺营业状态：&#123;&#125;&quot;,status); redisTemplate.opsForValue().set(StatusConstant.SHOP_STATUS, status); return Result.success(); &#125; @GetMapping(&quot;/status&quot;) @ApiOperation(&quot;管理端查询店铺营业状态&quot;) public Result&lt;Integer&gt; getStatus()&#123; Integer status = (Integer) redisTemplate.opsForValue().get(StatusConstant.SHOP_STATUS); log.info(&quot;查询店铺营业状态:&#123;&#125;&quot;,StatusConstant.SHOP_STATUS); return Result.success(status); &#125;&#125;
5. 微信登陆、商品浏览5.1 HttpClient5.1.1 介绍HttpClient是Apache Jakarta Common下的子项目，可以用来提供高效的、最新的、功能丰富的支持HTTP协议的客户端编程工具包，并且它支持HTTP协议最新的版本和建议。 &lt;dependency&gt; &lt;groupId&gt;org.apache.httpcomponents&lt;/groupId&gt; &lt;artifactId&gt;httpclient&lt;/artifactId&gt; &lt;version&gt;4.5.13&lt;/version&gt;&lt;/dependency&gt;
核心API HttpClient HttpClients CloseableHttpClient HttpGet HttpPost
发送请求步骤： 创建HttpClient对象 创建Http请求对象 调用HttpClient的excute方法发送请求
HttpClient作用： 可以在java程序中通过编码的方式发送Http请求 5.1.2 入门案例由于阿里云oss的sdk已经引入httpclient的maven坐标，所以不必再引入 package com.sky.test.server.httpclient;import com.alibaba.fastjson.JSONObject;import org.apache.http.HttpEntity;import org.apache.http.client.methods.CloseableHttpResponse;import org.apache.http.client.methods.HttpGet;import org.apache.http.client.methods.HttpPost;import org.apache.http.entity.StringEntity;import org.apache.http.impl.client.CloseableHttpClient;import org.apache.http.impl.client.HttpClients;import org.apache.http.util.EntityUtils;import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import java.io.IOException;@SpringBootTestpublic class HttpClientTest &#123; /** * GET 请求 */ @Test public void testGET() throws IOException &#123; //1. 创建HttpClient对象 CloseableHttpClient httpClient = HttpClients.createDefault(); //2. 创建请求对象 HttpGet httpGet = new HttpGet(&quot;http://localhost:8080/user/shop/status&quot;); //3. 发送请求 CloseableHttpResponse response = httpClient.execute(httpGet); // 4.获取服务端返回的状态码 int statusCode = response.getStatusLine().getStatusCode(); System.out.println(statusCode); // 5. 获取服务端返回的数据 HttpEntity entity = response.getEntity(); System.out.println(&quot;返回数据：&quot; + EntityUtils.toString(entity)); // 6. 关闭资源 response.close(); httpClient.close(); &#125; @Test public void testPost() throws IOException &#123; //1. 创建HttpClient对象 CloseableHttpClient httpClient = HttpClients.createDefault(); //2. 创建请求对象 HttpPost httpPost = new HttpPost(&quot;http://localhost:8080/admin/employee/login&quot;); JSONObject jsonObject = new JSONObject(); jsonObject.put(&quot;username&quot;, &quot;admin&quot;); jsonObject.put(&quot;password&quot;, &quot;123456&quot;); StringEntity stringEntity = new StringEntity(jsonObject.toString()); //指定编码方式和数据格式 stringEntity.setContentType(&quot;application/json&quot;); stringEntity.setContentEncoding(&quot;UTF-8&quot;); httpPost.setEntity(stringEntity); //3. 发送请求 CloseableHttpResponse response = httpClient.execute(httpPost); // 4.获取服务端返回的状态码 int statusCode = response.getStatusLine().getStatusCode(); System.out.println(statusCode); // 5. 获取服务端返回的数据 HttpEntity entity = response.getEntity(); System.out.println(&quot;返回数据：&quot; + EntityUtils.toString(entity)); // 6. 关闭资源 response.close(); httpClient.close(); &#125;&#125;
