6.3.2 代码开发@Autowiredprivate ShoppingCartMapper shoppingCartMapper;@Autowiredprivate DishMapper dishMapper;@Autowiredprivate SetmealMapper setmealMapper;@Overridepublic void addShoppingCart(ShoppingCartDTO shoppingCartDTO) &#123; // 判断当前用户加入到购物车中的商品是否已经存在 ShoppingCart shoppingCart = new ShoppingCart(); BeanUtils.copyProperties(shoppingCartDTO, shoppingCart); Long currentId = BaseContext.getCurrentId(); shoppingCart.setUserId(currentId); List&lt;ShoppingCart&gt; list = shoppingCartMapper.list(shoppingCart); if(list != null &amp;&amp; list.size() &gt; 0) &#123; ShoppingCart cart = list.get(0); cart.setNumber(cart.getNumber() + 1); // update shopping_cart set number = ? where id = ? shoppingCartMapper.updateNumberById(cart); &#125;else&#123; // 如果不存在，插入一条购物车数据 Long dishId = shoppingCartDTO.getDishId(); if(dishId != null)&#123; Dish dish = dishMapper.getById(dishId); shoppingCart.setName(dish.getName()); shoppingCart.setImage(dish.getImage()); shoppingCart.setAmount(dish.getPrice()); &#125;else&#123; Long setmealId = shoppingCartDTO.getSetmealId(); Setmeal setMeal = setmealMapper.getById(setmealId); shoppingCart.setName(setMeal.getName()); shoppingCart.setImage(setMeal.getImage()); shoppingCart.setAmount(setMeal.getPrice()); &#125; // 如果存在，只需要将数量+1 // 如果不存在，则需要插入一条购物车数据 shoppingCart.setNumber(1); shoppingCart.setCreateTime(LocalDateTime.now()); shoppingCartMapper.insert(shoppingCart); &#125;&#125;@Overridepublic List&lt;ShoppingCart&gt; list(Long userId) &#123; return shoppingCartMapper.list(ShoppingCart.builder().userId(userId).build());&#125;
