controller
@Autowiredprivate OrderService orderService;@PostMapping(&quot;/submit&quot;)@ApiOperation(&quot;用户端订单提交&quot;)public Result&lt;OrderSubmitVO&gt; submitOrder(@RequestBody OrdersSubmitDTO ordersSubmitDTO) &#123; log.info(&quot;用户下单，参数为:&#123;&#125;&quot;, ordersSubmitDTO); OrderSubmitVO orderSubmitVO = orderService.submitOrder(ordersSubmitDTO); return Result.success(orderSubmitVO);&#125;
service
package com.sky.service.impl;import com.sky.constant.MessageConstant;import com.sky.context.BaseContext;import com.sky.dto.OrdersSubmitDTO;import com.sky.entity.AddressBook;import com.sky.entity.OrderDetail;import com.sky.entity.Orders;import com.sky.entity.ShoppingCart;import com.sky.exception.AddressBookBusinessException;import com.sky.mapper.AddressBookMapper;import com.sky.mapper.OrderDetailMapper;import com.sky.mapper.OrderMapper;import com.sky.mapper.ShoppingCartMapper;import com.sky.service.OrderService;import com.sky.vo.OrderSubmitVO;import org.springframework.beans.BeanUtils;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.ArrayList;import java.util.List;@Servicepublic class OrderServiceImpl implements OrderService &#123; @Autowired private OrderMapper orderMapper; @Autowired private OrderDetailMapper orderDetailMapper; @Autowired private AddressBookMapper addressBookMapper; @Autowired private ShoppingCartMapper shoppingCartMapper; @Override @Transactional public OrderSubmitVO submitOrder(OrdersSubmitDTO ordersSubmitDTO) &#123; // 处理各种业务异常（地址簿为空、购物车为空） AddressBook addressBook = addressBookMapper.getById(ordersSubmitDTO.getAddressBookId()); if(addressBook == null)&#123; // 抛出业务异常 throw new AddressBookBusinessException(MessageConstant.ADDRESS_BOOK_IS_NULL); &#125; List&lt;ShoppingCart&gt; shoppingCartList = shoppingCartMapper.list(ShoppingCart.builder().userId(BaseContext.getCurrentId()).build()); if(shoppingCartList == null || shoppingCartList.isEmpty())&#123; throw new AddressBookBusinessException(MessageConstant.SHOPPING_CART_IS_NULL); &#125; // 1. 向订单表插入一条订单数据 Orders orders = new Orders(); BeanUtils.copyProperties(ordersSubmitDTO, orders); orders.setOrderTime(LocalDateTime.now()); orders.setPayStatus(Orders.UN_PAID); orders.setStatus(Orders.PENDING_PAYMENT); orders.setNumber(String.valueOf(System.currentTimeMillis())); orders.setPhone(addressBook.getPhone()); orders.setConsignee(addressBook.getConsignee()); orders.setUserId(BaseContext.getCurrentId()); orderMapper.insertOrder(orders); //2. 向订单明细表插入多条数据 List&lt;OrderDetail&gt; orderDetails = new ArrayList&lt;&gt;(); for(ShoppingCart shoppingCart : shoppingCartList)&#123; OrderDetail orderDetail = new OrderDetail(); BeanUtils.copyProperties(shoppingCart, orderDetail); orderDetail.setOrderId(orders.getId()); orderDetails.add(orderDetail); &#125; orderDetailMapper.insertBatch(orderDetails); //3. 清空当前用户的购物车数据 shoppingCartMapper.deleteByUserId(BaseContext.getCurrentId()); //4. 封装VO返回结果 return OrderSubmitVO.builder() .id(orders.getId()) .orderTime(orders.getOrderTime()) .orderNumber(orders.getNumber()) .orderAmount(orders.getAmount()) .build(); &#125;&#125;
