8. 订单状态定时处理、来单提醒和客户催单8.1 Spring Task8.1.1 介绍Spring Task是Spring框架提供的任务调度工具，可以按照约定的时间自动执行某个代码逻辑
应用场景：
信用卡每月还款提醒 在线支付应用处理未支付订单 某个纪念日为用户发送通知
使用步骤
启动类加@EnableScheduling 方法上加@Scheduled(cron = &quot;0/5 * * * * ?&quot;) (类上需要加上@Component注解)
8.1.2 cron表达式cron表达式可以理解为就是一个字符串，通过cron表达式可以定义任务的触发时间 构成规则：分成6或7个域，用空格分隔开，每个域代表一个含义 每个域的含义：秒 分 时 日 月 周 年(年可选) 2025年5月21日8点56分20秒
秒 分 时 日 月 周 年
20 56 08 21 5 ？（日和周只能有一个出现） 2022
, - * &#x2F; , - * &#x2F; , - * &#x2F; , - * &#x2F; L(每月最后一天) W(每月几号最近的工作日) , - * &#x2F; , - * &#x2F; L(1L本月最后一个星期1) #(3#4第三周的星期四) , - * &#x2F;
cron表达式在线生成器： https://cron.qqe2.com 8.1.3 入门案例 Spring Task 使用步骤 导入maven坐标 spring-context （spring boot默认已导入） 启动类添加注解@EnableScheduling开启任务调度 自定义定时任务类（需要加上@Component注解）
8.2 订单状态定时处理 需求分析
下单后未支付，订单一直处于“待支付”状态 用户收货后管理端没有点击完成，订单一直处于“派送中”状态
实现思路
通过定时任务每分钟检查一次是否存在支付超时订单，如果存在则修改订单状态为“已取消”
task
package com.sky.task;import com.sky.constant.MessageConstant;import com.sky.entity.Orders;import com.sky.mapper.OrderMapper;import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import java.time.LocalDateTime;import java.util.List;/** * 定时任务类，定时处理订单状态 */@Component@Slf4jpublic class OrderTask &#123; @Autowired OrderMapper orderMapper; /** * 处理超时订单的方法 */ @Scheduled(cron = &quot;*/10 * * * * ?&quot;) public void processTimeOutOrder()&#123; log.info(&quot;定时处理超时订单：&#123;&#125;&quot;, LocalDateTime.now()); // select * from orders where status = ? and order_time &lt; (当前时间-15分钟） List&lt;Orders&gt; orderList = orderMapper.getByStatusAndOrderTimeLT(Orders.PENDING_PAYMENT, LocalDateTime.now().plusMinutes(-15)); if(orderList != null &amp;&amp; orderList.size() &gt; 0)&#123; for (Orders orders : orderList) &#123; orders.setStatus(Orders.CANCELLED); orders.setCancelTime(LocalDateTime.now()); orders.setCancelReason(MessageConstant.ORDER_OVERTIME); &#125; orderMapper.batchUpdate(orderList); &#125; &#125; /** * 处理未处理的派送中订单 */ @Scheduled(cron = &quot;0 0 1 * * ?&quot;) // 每天凌晨1点 public void processDeliveryOrder()&#123; log.info(&quot;定时处理处于派送中的订单:&#123;&#125;&quot;, LocalDateTime.now()); List&lt;Orders&gt; orderList = orderMapper.getByStatusAndOrderTimeLT(Orders.DELIVERY_IN_PROGRESS, LocalDateTime.now().plusHours(-5)); if(orderList != null &amp;&amp; orderList.size() &gt; 0)&#123; for (Orders orders : orderList) &#123; orders.setStatus(Orders.CANCELLED); orders.setDeliveryTime(LocalDateTime.now()); &#125; orderMapper.batchUpdate(orderList); &#125; &#125;&#125;
mapper
&lt;update id=&quot;batchUpdate&quot; &gt; update orders &lt;set&gt; &lt;if test=&quot;list[0].cancelReason != null and list[0].cancelReason!=&#x27;&#x27; &quot;&gt; cancel_reason=#&#123;list[0].cancelReason&#125;, &lt;/if&gt; &lt;if test=&quot;list[0].rejectionReason != null and list[0].rejectionReason!=&#x27;&#x27; &quot;&gt; rejection_reason=#&#123;list[0].rejectionReason&#125;, &lt;/if&gt; &lt;if test=&quot;list[0].cancelTime != null&quot;&gt; cancel_time=#&#123;list[0].cancelTime&#125;, &lt;/if&gt; &lt;if test=&quot;list[0].payStatus != null&quot;&gt; pay_status=#&#123;list[0].payStatus&#125;, &lt;/if&gt; &lt;if test=&quot;list[0].payMethod != null&quot;&gt; pay_method=#&#123;list[0].payMethod&#125;, &lt;/if&gt; &lt;if test=&quot;list[0].checkoutTime != null&quot;&gt; checkout_time=#&#123;list[0].checkoutTime&#125;, &lt;/if&gt; &lt;if test=&quot;list[0].status != null&quot;&gt; status = #&#123;list[0].status&#125;, &lt;/if&gt; &lt;if test=&quot;list[0].deliveryTime != null&quot;&gt; delivery_time = #&#123;list[0].deliveryTime&#125; &lt;/if&gt; &lt;/set&gt; where id in &lt;foreach collection=&quot;orderList&quot; item=&quot;order&quot; separator=&quot;,&quot; open=&quot;(&quot; close=&quot;)&quot;&gt; #&#123;order.id&#125; &lt;/foreach&gt;
8.3 WebSocketWebSocket是基于TCP的一种新的网络协议。它实现了浏览器与服务器全双工通信—-浏览器和服务器只需要完成一次握手，两者之间就可以创建持久性的连接，并进行双向数据传输
单工通信只支持信号在一个方向上传输（正向或反向），任何时候不能改变信号的传输方向。
半双工通信允许信号在两个方向上传输，但某一时刻只允许信号在一个信道上单向传输。
全双工通信允许数据同时在两个方向上传输，即有两个信道，因此允许同时进行双向传输。
应用场景
视频弹幕 网页聊天 体育实况更新 股票基金报价实时更新
入门案例
实现步骤：
使用websocket.html页面作为WebSocket客户端
&lt;!DOCTYPE HTML&gt;&lt;html&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;title&gt;WebSocket Demo&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;input id=&quot;text&quot; type=&quot;text&quot; /&gt; &lt;button onclick=&quot;send()&quot;&gt;发送消息&lt;/button&gt; &lt;button onclick=&quot;closeWebSocket()&quot;&gt;关闭连接&lt;/button&gt; &lt;div id=&quot;message&quot;&gt; &lt;/div&gt;&lt;/body&gt;&lt;script type=&quot;text/javascript&quot;&gt; var websocket = null; var clientId = Math.random().toString(36).substr(2); //判断当前浏览器是否支持WebSocket if(&#x27;WebSocket&#x27; in window)&#123; //连接WebSocket节点 websocket = new WebSocket(&quot;ws://localhost:8080/ws/&quot;+clientId); &#125; else&#123; alert(&#x27;Not support websocket&#x27;) &#125; //连接发生错误的回调方法 websocket.onerror = function()&#123; setMessageInnerHTML(&quot;error&quot;); &#125;; //连接成功建立的回调方法 websocket.onopen = function()&#123; setMessageInnerHTML(&quot;连接成功&quot;); &#125; //接收到消息的回调方法 websocket.onmessage = function(event)&#123; setMessageInnerHTML(event.data); &#125; //连接关闭的回调方法 websocket.onclose = function()&#123; setMessageInnerHTML(&quot;close&quot;); &#125; //监听窗口关闭事件，当窗口关闭时，主动去关闭websocket连接，防止连接还没断开就关闭窗口，server端会抛异常。 window.onbeforeunload = function()&#123; websocket.close(); &#125; //将消息显示在网页上 function setMessageInnerHTML(innerHTML)&#123; document.getElementById(&#x27;message&#x27;).innerHTML += innerHTML + &#x27;&lt;br/&gt;&#x27;; &#125; //发送消息 function send()&#123; var message = document.getElementById(&#x27;text&#x27;).value; websocket.send(message); &#125; //关闭连接 function closeWebSocket() &#123; websocket.close(); &#125;&lt;/script&gt;&lt;/html&gt;
导入WebSocket的maven坐标
&lt;dependency&gt; &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt; &lt;artifactId&gt;spring-boot-starter-websocket&lt;/artifactId&gt;&lt;/dependency&gt;
导入WebSocket服务端组件WebSocketServer, 用于和客户端通信
导入配置类WebSocketConfiguration，注册WebSocket服务端组件
导入定时任务类WebSocketTask，定时向客户端推送数据
8.4 来单提醒设计：
通过WebSocket实现管理端页面和服务端保持长连接状态 当客户支付后，调用WebSocket的相关API实现服务端向客户端推送消息 客户端浏览器解析服务端推送的消息，判断是来单提醒还是客户催单，进行相应的消息提示和语音播报 约定服务端发送给客户端浏览器的数据格式为JSON，字段包括：type、orderId、content type：消息类型，1为来单提醒、2为客户催单 orderId：为订单id content：为消息内容
8.5 客户催单 需求分析 用户在小程序中点击催单按钮，需要第一时间通知外卖商家，通知形式有： 语音播报 弹出提示框
9.数据统计-图形报表9.1 Apache Echarts9.1.1 介绍Apache Echarts是一款基于JavaScript的数据可视化图标库，提供直观、生动、可交互、可个性化定制的数据可视化图标 官网地址： https://echarts.apache.org/zh/index.html 9.1.2 入门案例使用Echarts，重点在于研究当前图标所需的数据格式，通常是需要后端提供符合格式要求的动态数据，然后响应前端来展示图标 9.2 营业额统计9.2.1 需求分析和设计
9.2.2 代码开发 controller
@RestController@Slf4j@RequestMapping(&quot;/admin/report&quot;)@Api(tags = &quot;数据统计相关接口&quot;)public class ReportController &#123; @Autowired private ReportService reportService; @GetMapping(&quot;/turnoverStatistics&quot;) @ApiOperation(&quot;获取营业额数据&quot;) public Result&lt;TurnoverReportVO&gt; turnoverStatistics( @DateTimeFormat(pattern = &quot;yyyy-MM-dd&quot;) LocalDate begin, @DateTimeFormat(pattern = &quot;yyyy-MM-dd&quot;) LocalDate end) &#123; log.info(&quot;营业额数据统计：start = &#123;&#125;, end = &#123;&#125;&quot;, begin, end); return Result.success(reportService.getTurnoverStatistics(begin,end)); &#125;&#125;
service
package com.sky.service.impl;import com.sky.entity.Orders;import com.sky.mapper.OrderMapper;import com.sky.service.ReportService;import com.sky.vo.TurnoverReportVO;import lombok.extern.slf4j.Slf4j;import org.apache.commons.lang3.StringUtils;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import java.time.LocalDate;import java.time.LocalDateTime;import java.time.LocalTime;import java.util.*;@Service@Slf4jpublic class ReportServiceImpl implements ReportService &#123; @Autowired private OrderMapper orderMapper; @Override public TurnoverReportVO getTurnoverStatistics(LocalDate begin, LocalDate end) &#123; // 当前集合用于存放begin到end范围内的每天的日期 List&lt;LocalDate&gt; dateList = new ArrayList&lt;&gt;(); dateList.add(begin); while(!begin.equals(end)) &#123; begin = begin.plusDays(1); dateList.add(begin); &#125; List&lt;Double&gt; turnoverList = new ArrayList&lt;&gt;(); for(LocalDate date : dateList) &#123; LocalDateTime dayStart = LocalDateTime.of(date, LocalTime.MIN); LocalDateTime dayEnd = LocalDateTime.of(date, LocalTime.MAX); Map&lt;String, Object&gt; map = new HashMap&lt;&gt;(); map.put(&quot;dayStart&quot;, dayStart.toString()); map.put(&quot;dayEnd&quot;, dayEnd.toString()); map.put(&quot;status&quot;, Orders.COMPLETED); Double turnover = orderMapper.sumByMap(map); turnover = turnover == null ? 0.0 : turnover; turnoverList.add(turnover); &#125; //封装返回结果 return TurnoverReportVO.builder() .dateList(StringUtils.join(dateList, &quot;,&quot;)) .turnoverList(StringUtils.join(turnoverList, &quot;,&quot;)) .build(); &#125;&#125;
mapper
&lt;select id=&quot;sumByMap&quot; resultType=&quot;java.lang.Double&quot; parameterType=&quot;Map&quot;&gt; select sum(amount) from orders &lt;where&gt; &lt;if test=&quot;dayStart != null&quot;&gt; and delivery_time &gt; #&#123;dayStart&#125; &lt;/if&gt; &lt;if test=&quot;dayEnd != null&quot;&gt; and delivery_time &amp;lt; #&#123;dayEnd&#125; &lt;/if&gt; &lt;if test=&quot;status != null&quot;&gt; and status = #&#123;status&#125; &lt;/if&gt; &lt;/where&gt;&lt;/select&gt;
9.3 用户统计public UserReportVO getUserStatistics(LocalDate begin, LocalDate end) &#123; List&lt;LocalDate&gt; dateList = new ArrayList&lt;&gt;(); dateList.add(begin); while(!begin.equals(end))&#123; begin = begin.plusDays(1); dateList.add(begin); &#125; // select sum(id) from user where create_time &gt; ? and create_time &lt; ? List&lt;Integer&gt; newUserList = new ArrayList&lt;&gt;(); // select sum(id) from user where create_time &lt; ? List&lt;Integer&gt; totalUserList = new ArrayList&lt;&gt;(); for(LocalDate date : dateList) &#123; LocalDateTime dayStart = LocalDateTime.of(date, LocalTime.MIN); LocalDateTime dayEnd = LocalDateTime.of(date, LocalTime.MAX); Map&lt;String, Object&gt; map = new HashMap&lt;&gt;(); map.put(&quot;dayEnd&quot;, dayEnd.toString()); Integer totalUser = userMapper.countByMap(map); map.put(&quot;dayStart&quot;, dayStart.toString()); Integer newUser = userMapper.countByMap(map); newUserList.add(newUser); totalUserList.add(totalUser); &#125; return UserReportVO.builder() .dateList(StringUtils.join(dateList,&quot;,&quot;)) .newUserList(StringUtils.join(newUserList,&quot;,&quot;)) .totalUserList(StringUtils.join(totalUserList,&quot;,&quot;)) .build(); &#125;
&lt;select id=&quot;countByMap&quot; resultType=&quot;java.lang.Integer&quot;&gt; select count(id) from user &lt;where&gt; &lt;if test=&quot;dayStart != null&quot;&gt; and create_time &gt; #&#123;dayStart&#125; &lt;/if&gt; &lt;if test=&quot;dayEnd != null&quot;&gt; and create_time &amp;lt; #&#123;dayEnd&#125; &lt;/if&gt; &lt;/where&gt;&lt;/select&gt;
9.4 订单统计&lt;select id=&quot;countByMap&quot; resultType=&quot;java.lang.Integer&quot;&gt; select count(id) from orders &lt;where&gt; &lt;if test=&quot;dayStart != null&quot;&gt; and order_time &amp;gt; #&#123;dayStart&#125; &lt;/if&gt; &lt;if test=&quot;dayEnd != null&quot;&gt; and order_time &amp;lt; #&#123;dayEnd&#125; &lt;/if&gt; &lt;if test=&quot;status != null&quot;&gt; and status = #&#123;status&#125; &lt;/if&gt; &lt;/where&gt;&lt;/select&gt;
9.5 销量排名TOP10&lt;select id=&quot;getTop10&quot; resultType=&quot;com.sky.vo.SalesTop10ReportVO&quot;&gt; SELECT GROUP_CONCAT(name ORDER BY sn DESC SEPARATOR &#x27;,&#x27;) AS nameList, GROUP_CONCAT(sn ORDER BY sn DESC SEPARATOR &#x27;,&#x27;) AS numberList FROM ( SELECT ANY_VALUE(d.name) as name, SUM(d.number) as sn FROM order_detail as d INNER JOIN orders as o ON d.order_id = o.id &lt;where&gt; &lt;if test=&quot;status != null&quot;&gt; and o.status = #&#123;status&#125; &lt;/if&gt; &lt;if test=&quot;dayStart != null&quot;&gt; and o.order_time &amp;gt; #&#123;dayStart&#125; &lt;/if&gt; &lt;if test=&quot;dayEnd != null&quot;&gt; and o.order_time &amp;lt; #&#123;dayEnd&#125; &lt;/if&gt; &lt;/where&gt; GROUP BY d.dish_id ORDER BY sn DESC LIMIT 10 ) AS top10&lt;/select&gt;
10 导出Excel报表10.1 Apache POI 介绍
Apache POI 是一个处理Microsoft office各种文件格式的开源项目。可以使用POI在Java程序中对各种office文件进行读写操作。POI通常用于处理Excel文件 应用场景： · 银行网银系统导出交易明细 · 各种业务系统导出Excel报表 · 批量导入业务数据
入门案例
导入maven坐标
&lt;properties&gt; &lt;poi&gt;3.16&lt;/poi&gt; &lt;/properties&gt; &lt;!-- poi --&gt; &lt;dependency&gt; &lt;groupId&gt;org.apache.poi&lt;/groupId&gt; &lt;artifactId&gt;poi&lt;/artifactId&gt; &lt;version&gt;$&#123;poi&#125;&lt;/version&gt; &lt;/dependency&gt; &lt;dependency&gt; &lt;groupId&gt;org.apache.poi&lt;/groupId&gt; &lt;artifactId&gt;poi-ooxml&lt;/artifactId&gt; &lt;version&gt;$&#123;poi&#125;&lt;/version&gt; &lt;/dependency&gt;
10.2 导入运营数据10.2.1 分析设计 10.2.2 代码开发package com.sky.service.impl;import com.sky.entity.Orders;import com.sky.mapper.OrderDetailMapper;import com.sky.mapper.OrderMapper;import com.sky.mapper.UserMapper;import com.sky.service.ReportService;import com.sky.service.WorkspaceService;import com.sky.vo.*;import lombok.extern.slf4j.Slf4j;import org.apache.commons.lang3.StringUtils;import org.apache.poi.xssf.usermodel.XSSFRow;import org.apache.poi.xssf.usermodel.XSSFSheet;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import javax.servlet.ServletOutputStream;import javax.servlet.http.HttpServletResponse;import java.io.IOException;import java.io.InputStream;import java.time.LocalDate;import java.time.LocalDateTime;import java.time.LocalTime;import java.util.*;@Service@Slf4jpublic class ReportServiceImpl implements ReportService &#123; @Autowired private OrderMapper orderMapper; @Autowired private UserMapper userMapper; @Autowired private OrderDetailMapper orderDetailMapper; @Autowired private WorkspaceService workspaceService; @Override public TurnoverReportVO getTurnoverStatistics(LocalDate begin, LocalDate end) &#123; // 当前集合用于存放begin到end范围内的每天的日期 List&lt;LocalDate&gt; dateList = new ArrayList&lt;&gt;(); dateList.add(begin); while(!begin.equals(end)) &#123; begin = begin.plusDays(1); dateList.add(begin); &#125; List&lt;Double&gt; turnoverList = new ArrayList&lt;&gt;(); for(LocalDate date : dateList) &#123; LocalDateTime dayStart = LocalDateTime.of(date, LocalTime.MIN); LocalDateTime dayEnd = LocalDateTime.of(date, LocalTime.MAX); Map&lt;String, Object&gt; map = new HashMap&lt;&gt;(); map.put(&quot;dayStart&quot;, dayStart.toString()); map.put(&quot;dayEnd&quot;, dayEnd.toString()); map.put(&quot;status&quot;, Orders.COMPLETED); Double turnover = orderMapper.sumByMap(map); turnover = turnover == null ? 0.0 : turnover; turnoverList.add(turnover); &#125; //封装返回结果 return TurnoverReportVO.builder() .dateList(StringUtils.join(dateList, &quot;,&quot;)) .turnoverList(StringUtils.join(turnoverList, &quot;,&quot;)) .build(); &#125; @Override public UserReportVO getUserStatistics(LocalDate begin, LocalDate end) &#123; List&lt;LocalDate&gt; dateList = new ArrayList&lt;&gt;(); dateList.add(begin); while(!begin.equals(end))&#123; begin = begin.plusDays(1); dateList.add(begin); &#125; // select sum(id) from user where create_time &gt; ? and create_time &lt; ? List&lt;Integer&gt; newUserList = new ArrayList&lt;&gt;(); // select sum(id) from user where create_time &lt; ? List&lt;Integer&gt; totalUserList = new ArrayList&lt;&gt;(); for(LocalDate date : dateList) &#123; LocalDateTime dayStart = LocalDateTime.of(date, LocalTime.MIN); LocalDateTime dayEnd = LocalDateTime.of(date, LocalTime.MAX); Map&lt;String, Object&gt; map = new HashMap&lt;&gt;(); map.put(&quot;dayEnd&quot;, dayEnd.toString()); Integer totalUser = userMapper.countByMap(map); map.put(&quot;dayStart&quot;, dayStart.toString()); Integer newUser = userMapper.countByMap(map); newUserList.add(newUser); totalUserList.add(totalUser); &#125; return UserReportVO.builder() .dateList(StringUtils.join(dateList,&quot;,&quot;)) .newUserList(StringUtils.join(newUserList,&quot;,&quot;)) .totalUserList(StringUtils.join(totalUserList,&quot;,&quot;)) .build(); &#125; @Override public OrderReportVO getOrderStatistics(LocalDate begin, LocalDate end) &#123; List&lt;LocalDate&gt; dateList = new ArrayList&lt;&gt;(); dateList.add(begin); while(!begin.equals(end))&#123; begin = begin.plusDays(1); dateList.add(begin); &#125; // 查询每天订单数和有效的订单数 List&lt;Integer&gt; newOrderList = new ArrayList&lt;&gt;(); List&lt;Integer&gt; validOrderList = new ArrayList&lt;&gt;(); for(LocalDate date : dateList) &#123; // 查询订单总数 select count(id) from orders where order_time &amp;lt; ? and order_time &amp;gt; ? LocalDateTime dayStart = LocalDateTime.of(date, LocalTime.MIN); LocalDateTime dayEnd = LocalDateTime.of(date, LocalTime.MAX); Integer orderCount = getOrderCount(dayStart, dayEnd, null); //查询有效订单数 select count(id) from orders where order_time &gt; ? and order_time &lt; ? and status = completed Integer validOrderCount = getOrderCount(dayStart, dayEnd, Orders.COMPLETED); newOrderList.add(orderCount); validOrderList.add(validOrderCount); &#125; //计算时间区间内订单总数 Integer totalOrderCount = newOrderList.stream().reduce(Integer::sum).get(); Integer validOrderCount = validOrderList.stream().reduce(Integer::sum).get(); return OrderReportVO.builder() .dateList(StringUtils.join(dateList,&quot;,&quot;)) .validOrderCountList(StringUtils.join(validOrderList,&quot;,&quot;)) .orderCountList(StringUtils.join(newOrderList,&quot;,&quot;)) .totalOrderCount(totalOrderCount) .validOrderCount(totalOrderCount) .orderCompletionRate(totalOrderCount == 0 ? 0.0 : validOrderCount.doubleValue() / totalOrderCount.doubleValue()) .build(); &#125; @Override public SalesTop10ReportVO getTop10(LocalDate begin, LocalDate end) &#123; LocalDateTime dayStart = LocalDateTime.of(begin, LocalTime.MIN); LocalDateTime dayEnd = LocalDateTime.of(end, LocalTime.MAX); List&lt;String&gt; top10NameList = new ArrayList&lt;&gt;(); List&lt;Integer&gt; top10CountList = new ArrayList&lt;&gt;(); // select d.dish_id, ANY_VALUE(name) as name, sum(d.number) as sn from order_detail as d left join orders as o group by d.dish_id having o.status = #&#123;status&#125; order by sn DESC; return orderDetailMapper.getTop10(dayStart,dayEnd,Orders.COMPLETED); &#125; @Override public void reportBusinessData(HttpServletResponse response) &#123; // 1. 查询数据库，获取运营数据 LocalDate startDate = LocalDate.now().minusDays(30); LocalDate endDate = LocalDate.now().minusDays(1); BusinessDataVO businessData = workspaceService.getBusinessData(LocalDateTime.of(startDate, LocalTime.MIN), LocalDateTime.of(endDate, LocalTime.MAX)); // 2. 通过POI写入数据 InputStream in = this.getClass().getClassLoader().getResourceAsStream(&quot;template/运营数据报表模板.xlsx&quot;); ServletOutputStream outputStream = null; XSSFWorkbook sheets = null; try &#123; sheets = new XSSFWorkbook(in); // 填充数据 XSSFSheet sheet1 = sheets.getSheet(&quot;Sheet1&quot;); sheet1.getRow(1).getCell(1).setCellValue(&quot;时间: &quot; + startDate + &quot; -- &quot; + endDate); sheet1.getRow(3).getCell(2).setCellValue(businessData.getTurnover()); sheet1.getRow(3).getCell(4).setCellValue(businessData.getOrderCompletionRate()); sheet1.getRow(3).getCell(6).setCellValue(businessData.getNewUsers()); sheet1.getRow(4).getCell(2).setCellValue(businessData.getValidOrderCount()); sheet1.getRow(4).getCell(4).setCellValue(businessData.getUnitPrice()); //sheet1.getRow(7).getCell(2) for (int i = 0; i &lt; 30; i++) &#123; LocalDate localDate = startDate.plusDays(i); BusinessDataVO dayData = workspaceService.getBusinessData(LocalDateTime.of(localDate, LocalTime.MIN), LocalDateTime.of(localDate, LocalTime.MAX)); sheet1.getRow(7 + i).getCell(1).setCellValue(localDate.toString()); sheet1.getRow(7 + i).getCell(2).setCellValue(dayData.getTurnover()); sheet1.getRow(7 + i).getCell(3).setCellValue(dayData.getValidOrderCount()); sheet1.getRow(7 + i).getCell(4).setCellValue(dayData.getOrderCompletionRate()); sheet1.getRow(7 + i).getCell(5).setCellValue(dayData.getUnitPrice()); sheet1.getRow(7 + i).getCell(6).setCellValue(dayData.getNewUsers()); &#125; // 3. 通过输出流，传输到客户端 outputStream = response.getOutputStream(); sheets.write(outputStream); outputStream.close(); sheets.close(); &#125; catch (IOException e) &#123; throw new RuntimeException(e); &#125; &#125; private Integer getOrderCount(LocalDateTime begin, LocalDateTime end, Integer status) &#123; Map&lt;String, Object&gt; map = new HashMap&lt;&gt;(); map.put(&quot;dayStart&quot;, begin); map.put(&quot;dayEnd&quot;, end); map.put(&quot;status&quot;, status); return orderMapper.countByMap(map); &#125;&#125;
11. 前端部分11.1 vue基础回顾11.1.1 基于脚手架创建前端工程 使用Vue CLI创建前端工程：
方式一：vue create 项目名称
npm i @vue/cli -gvue create vue-demo-1
方式二：vue ui
vue ui
修改前端服务端口号
11.1.2 vue基本使用方式vue组件vue的组件文件以.vue结尾，每个组件由三部分组成： 结构 样式 逻辑
&lt;template&gt; &lt;div id=&quot;app&quot;&gt; &lt;!--只能有一个根元素，如果有与此平级的div，则会报错--&gt; &lt;img alt=&quot;Vue logo&quot; src=&quot;./assets/logo.png&quot;&gt; &lt;HelloWorld msg=&quot;Welcome to Your Vue.js App&quot;/&gt; &lt;/div&gt;&lt;/template&gt;&lt;script&gt;import HelloWorld from &#x27;./components/HelloWorld.vue&#x27;export default &#123; name: &#x27;App&#x27;, components: &#123; HelloWorld &#125;&#125;&lt;/script&gt;&lt;style&gt;#app &#123; font-family: Avenir, Helvetica, Arial, sans-serif; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; text-align: center; color: #2c3e50; margin-top: 60px;&#125;&lt;/style&gt;
文本插值作用： 用来绑定data方法返回的对象属性 用法: &#123;&#123;&#125;&#125; &lt;template&gt; &lt;div&gt; &lt;h1&gt; &#123;&#123;age &gt; 60 ? name : &quot;青年&quot;&#125;&#125; &lt;/h1&gt; &lt;/div&gt;&lt;/template&gt;&lt;script&gt; export default&#123; data() &#123; return &#123;name: &quot;老年&quot;, age: 70&#125; &#125; &#125;&lt;/script&gt;
属性绑定作用：为标签的属性绑定data方法中返回的属性 用法： v-bind:xxx，简写为:xxx &lt;template&gt; &lt;div class=&quot;hello&quot;&gt; &lt;div&gt;&lt;input type=&quot;text&quot; :value=&quot;age&quot;&gt;&lt;/div&gt; &lt;div&gt;&lt;img :src=&quot;src&quot;&gt;&lt;/div&gt; &lt;/div&gt;&lt;/template&gt;&lt;script&gt;export default &#123; data() &#123; return &#123;age: 50, name: &quot;张三&quot;, src:&quot;https://img-s.msn.cn/tenant/amp/entityid/BB1msKEx?w=0&amp;h=0&amp;q=60&amp;m=6&amp;f=jpg&amp;u=t&quot;&#125;; &#125;,&#125;
事件绑定作用：为元素绑定对应的事件 用法：v-on:xxx简写为@xxx &lt;template&gt; &lt;div class=&quot;hello&quot;&gt; &lt;div&gt; &lt;input type=&quot;button&quot; value=&quot;Save&quot; @click=&quot;save&quot;/&gt; &lt;/div&gt; &lt;/div&gt;&lt;/template&gt;&lt;script&gt;export default &#123; name: &#x27;HelloWorld&#x27;, methods: &#123; save() &#123; alert(this.name) &#125; &#125;&#125;&lt;/script&gt;
双向绑定作用：表单输入项和data方法中的属性进行绑定，任意一方改变都会同步给另一方 (输入框和data中的任意地方改变都会影响另一边) 用法： v-model &lt;template&gt; &lt;div class=&quot;hello&quot;&gt; &lt;h2&gt;&#123;&#123; name&#125;&#125;&lt;/h2&gt; &lt;input type=&quot;text&quot; v-model=&quot;name&quot;&gt; &lt;div&gt; &lt;input type=&quot;button&quot; value=&quot;点击改变&quot; @click=&quot;change&quot;/&gt; &lt;/div&gt; &lt;/div&gt;&lt;/template&gt;&lt;script&gt;export default &#123; data() &#123; return &#123; name: &quot;张三&quot;&#125;; &#125;, methods: &#123; change() &#123; this.name = &quot;李四&quot; &#125; &#125;&#125;&lt;/script&gt;
条件渲染作用： 根据表达式的值来动态渲染页面元素 用法： v-if,v-else,v-else-if &lt;template&gt; &lt;div class=&quot;hello&quot;&gt; &lt;div&gt; &lt;div v-if=&quot;sex == 1&quot;&gt; 男 &lt;/div&gt; &lt;div v-else-if=&quot;sex == 0&quot;&gt; 女&lt;/div&gt; &lt;div v-else&gt; 未知&lt;/div&gt; &lt;/div&gt; &lt;/div&gt;&lt;/template&gt;&lt;script&gt;export default &#123; data() &#123; return &#123; sex: 0&#125;; &#125;&lt;/script&gt;
axios （异步）Axios是一个基于promise的网络请求库，作用与浏览器和node.js中 安装命令：npm install axios 导入命令： import axios from &#39;axios&#39;
为了解决跨域问题，可以在vue.config.js文件中配置代理： const &#123; defineConfig &#125; = require(&#x27;@vue/cli-service&#x27;)module.exports = defineConfig(&#123; transpileDependencies: true, devServer:&#123; port:7070, proxy: &#123; // 对前端的请求，前缀是/api的进行代理 &#x27;/api&#x27;: &#123; target: &quot;http://localhost:8080&quot;, pathRewrite: &#123; // 将api请求前缀去掉 ==&gt; 将/api替换为空字符串 &quot;^/api&quot;: &#x27;&#x27; &#125; &#125; &#125; &#125;, &#125;)
&lt;template&gt;&lt;div&gt; &lt;input type=&quot;button&quot; value=&#x27;get方式请求&#x27; @click=&quot;getMethod&quot;/&gt;&lt;/div&gt;&lt;/template&gt;&lt;script&gt;import axios from &#x27;axios&#x27;export default &#123; methods: &#123; getMethod()&#123; axios.get(&quot;/api/admin/shop/status&quot;,&#123; headers:&#123; token: &quot;eyJhbGciOiJIUzI1NiJ9.eyJlbXBJZCI6MSwiZXhwIjoxNzQ4NjI1MjUwfQ.2UbrxjgMvSqiottavZ0M8r4zBOc8qNzh2Rr_fhFp7dw&quot; &#125; &#125;).then(res =&gt; &#123; console.log(res.data), console.log(res.data.code) &#125;) &#125; &#125;&#125;&lt;/script&gt;
另一种axios请求方式 getMethod2()&#123; axios(&#123; //默认使用get mehtod: &#x27;post&#x27;, url:&#x27;/api/admin/shop/status&#x27;, data: &#123; data01: 1, data02: &quot;2&quot; &#125;, headers:&#123; token: &quot;eyJhbGciOiJIUzI1NiJ9.eyJlbXBJZCI6MSwiZXhwIjoxNzQ4NjI1MjUwfQ.2UbrxjgMvSqiottavZ0M8r4zBOc8qNzh2Rr_fhFp7dw&quot; &#125; &#125;).then(res =&gt; &#123; console.log(res.data), console.log(res.data.code) &#125;)&#125;
11.2 Vue-Router11.2.1 Vue-Router 介绍vue属于单页面应用，所谓的路由，就是根据浏览器路径不同，用不同的视图组件替换这个页面内容 使用vue ui然后手动配置或者使用npm install vue-router 11.2.2 路由配置 路由组成 VueRouter：路由器，根据路由请求在路由视图中动态渲染对应的视图组件 &lt;router-link&gt;: 路由链接组件，浏览器会解析成&lt;a&gt; router-view: 路由视图组件， 用来展示与路由路径匹配的组件
路由链接组件和路由视图组件
&lt;template&gt; &lt;div id=&quot;app&quot;&gt; &lt;!-- 路由链接组件 --&gt; &lt;nav&gt; &lt;router-link to=&quot;/&quot;&gt;Home&lt;/router-link&gt; | &lt;router-link to=&quot;/about&quot;&gt;About&lt;/router-link&gt; &lt;/nav&gt; &lt;!-- 路由视图组件展示的位置 --&gt; &lt;router-view/&gt; &lt;/div&gt;&lt;/template&gt;
路由表
import Vue from &#x27;vue&#x27;import VueRouter from &#x27;vue-router&#x27;import HomeView from &#x27;../views/HomeView.vue&#x27;Vue.use(VueRouter)// 维护路由表，某个路由路径对应哪个视图组件const routes = [ &#123; path: &#x27;/&#x27;, name: &#x27;home&#x27;, component: HomeView // 静态加载 &#125;, &#123; path: &#x27;/about&#x27;, name: &#x27;about&#x27;, // route level code-splitting // this generates a separate chunk (about.[hash].js) for this route // which is lazy-loaded when the route is visited. 懒加载 component: () =&gt; import(/* webpackChunkName: &quot;about&quot; */ &#x27;../views/AboutView.vue&#x27;) &#125;]const router = new VueRouter(&#123; routes&#125;)export default router
路由配置
路由路径和视图对应关系配置 ./router/index.js &lt;router-link&gt;: ./App.vue &lt;router-view&gt;: ./App.vue
&lt;router-link&gt;路由跳转方式：
标签式：./App.vue 编程式: ./App.vue
&lt;template&gt; &lt;div id=&quot;app&quot;&gt; &lt;!-- 路由链接组件 --&gt; &lt;nav&gt; &lt;!-- 标签式路由跳转 --&gt; &lt;router-link to=&quot;/&quot;&gt;Home&lt;/router-link&gt; | &lt;router-link to=&quot;/about&quot;&gt;About&lt;/router-link&gt; &lt;!-- 编程式路由跳转 --&gt; &lt;input type=&quot;button&quot; value=&quot;编程式跳转&quot; @click=&quot;jump&quot;/&gt; &lt;/nav&gt; &lt;!-- 路由视图组件展示的位置 --&gt; &lt;router-view/&gt; &lt;/div&gt;&lt;/template&gt;&lt;script&gt;export default &#123; methods: &#123; jump() &#123; this.$router.push(&quot;/&quot;) &#125; &#125;&#125;&lt;/script&gt;
重定向
&#123; path: &#x27;/404&#x27;, component: () =&gt; import(&quot;../views/404View.vue&quot;)&#125;,&#123; path: &#x27;*&#x27;, redirect: &quot;/404&quot;&#125;
11.2.3 嵌套路由嵌套路由： 组件内要切换内容，就需要用到嵌套路由（子路由）
安装: npm i element-ui -S vue3使用element-ui-plus 导入
import Vue from &#x27;vue&#x27;import App from &#x27;./App.vue&#x27;import router from &#x27;./router&#x27;import ElementUI from &#x27;element-ui&#x27;import &#x27;element-ui/lib/theme-chalk/index.css&#x27;Vue.config.productionTip = false// 全局使用ElementUIVue.use(ElementUI)new Vue(&#123; router, render: h =&gt; h(App)&#125;).$mount(&#x27;#app&#x27;)
提供子视图
&lt;template&gt; &lt;div&gt; 这是P1 &lt;/div&gt;&lt;/template&gt;
路由配置
&#123; path: &#x27;/c&#x27;, component: () =&gt; import(&quot;../views/container/containerView.vue&quot;), children: [ // 嵌套子路由 &#123; path: &#x27;/c/p1&#x27;, component: () =&gt; import(&quot;../views/container/P1View.vue&quot;) &#125;, &#123; path: &#x27;/c/p2&#x27;, component: () =&gt; import(&quot;../views/container/P2View.vue&quot;) &#125;, &#123; path: &#x27;/c/p3&#x27;, component: () =&gt; import(&quot;../views/container/P3View.vue&quot;) &#125; ]&#125;
布局容器中添加&lt;router-view&gt;和&lt;router-link&gt;
&lt;template&gt; &lt;el-container&gt; &lt;el-header&gt;Header&lt;/el-header&gt; &lt;el-container&gt; &lt;el-aside width=&quot;200px&quot;&gt; &lt;router-link to=&quot;/c/p1&quot;&gt; P1 View&lt;/router-link&gt; &lt;br&gt; &lt;router-link to=&quot;/c/p2&quot;&gt; p2 view&lt;/router-link&gt; &lt;br&gt; &lt;router-link to=&#x27;/c/p3&#x27;&gt; p3 view&lt;/router-link&gt; &lt;/el-aside&gt; &lt;el-main&gt; &lt;!-- P1 P2 P3 替换的位置 --&gt; &lt;router-view/&gt; &lt;/el-main&gt; &lt;/el-container&gt; &lt;/el-container&gt;&lt;/template&gt;
11.3 状态管理vuex11.3.1 vuex介绍 vuex是一个专门为Vue.js应用程序开发的状态管理库 vuex可以在多个组件之间共享数据，并且共享的数据是响应式的，即数据的变更能及时渲染到模板 vuex采用集中式存储管理所有组件的状态
安装： npm install vuex@next --save 核心概念 state：状态对象，集中定义各个组件共享的数据 mutations： 类似一个事件，用于修改共享数据，要求必须是同步函数 actions： 类似于mutation，可以包含异步操作，通过调用mutation来改变共享数据
11.3.2 使用方式创建带有vuex功能的脚手架工程 定义共享数据./store/index.jsimport Vue from &#x27;vue&#x27;import Vuex from &#x27;vuex&#x27;Vue.use(Vuex)export default new Vuex.Store(&#123; //共享数据 state: &#123; name: &quot;未登录游客&quot; &#125;, getters: &#123; &#125;, //修改共享数据时只能通过mutation实现，必须是同步操作 mutations: &#123; &#125;, //通过action可以调用到mutation，action中可以进行异步操作 actions: &#123; &#125;, modules: &#123; &#125;&#125;)
使用 &lt;template&gt; &lt;div class=&quot;hello&quot;&gt; &lt;h1&gt;&#123;&#123; msg &#125;&#125;&lt;/h1&gt; &lt;h1&gt;&#123;&#123;$store.state.name&#125;&#125;&lt;/h1&gt; &lt;/div&gt;&lt;/template&gt;
在mutations中定义函数，修改共享数据import Vue from &#x27;vue&#x27;import Vuex from &#x27;vuex&#x27;Vue.use(Vuex)export default new Vuex.Store(&#123; //共享数据 state: &#123; name: &quot;未登录游客&quot; &#125;, getters: &#123; &#125;, //修改共享数据时只能通过mutation实现，必须是同步操作 mutations: &#123; setName(state,name)&#123; state.name = name &#125; &#125;, //通过action可以调用到mutation，action中可以进行异步操作 actions: &#123; &#125;, modules: &#123; &#125;&#125;)
使用 &lt;template&gt; &lt;div id=&quot;app&quot;&gt; &lt;input type=&quot;button&quot; value=&quot;通过mutations修改state&quot; @click=&quot;handleUpdate&quot;/&gt; &lt;/div&gt;&lt;/template&gt;&lt;script&gt; export default &#123; name: &quot;App&quot;, methods: &#123; handleUpdate()&#123; // mutation中的函数不能直接调用，必须使用如下方式调用 this.$store.commit(&#x27;setName&#x27;, &quot;新名字，李四&quot;) &#125; &#125; &#125;&lt;/script&gt;
在actions中定义函数，用于调用mutation安装axios：npm install axios 定义actions函数： import Vue from &#x27;vue&#x27;import Vuex from &#x27;vuex&#x27;import axios from &#x27;axios&#x27;Vue.use(Vuex) export default new Vuex.Store(&#123; //共享数据 state: &#123; name: &quot;未登录游客&quot; &#125;, getters: &#123; &#125;, //修改共享数据时只能通过mutation实现，必须是同步操作 mutations: &#123; setName(state,name)&#123; state.name = name &#125; &#125;, //通过action可以调用到mutation，action中可以进行异步操作 actions: &#123; setNameByAxios(context)&#123; axios(&#123; url: &#x27;/api/admin/employee/login&#x27;, method: &#x27;post&#x27;, data: &#123; username: &quot;admin&quot;, password: &#x27;123456&#x27; &#125; &#125;).then(res =&gt; &#123; if(res.data.code == 1)&#123; //异步请求后，需要修改共享数据 // actions中调用mutation定义的函数setName context.commit(&#x27;setName&#x27;, res.data.data.name) &#125; &#125;) &#125; &#125;, modules: &#123; &#125;&#125;)
App.vue中使用 &lt;template&gt; &lt;div id=&quot;app&quot;&gt; &lt;input type=&#x27;button&#x27; value=&quot;员工登录换名&quot; @click=&quot;handleLogin&quot;/&gt; &lt;/div&gt;&lt;/template&gt;&lt;script&gt; export default &#123; name: &quot;App&quot;, methods: &#123; handleLogin()&#123; // 调用actions当中的函数 setNameByAxios this.$store.dispatch(&#x27;setNameByAxios&#x27;) &#125; &#125; &#125;&lt;/script&gt;
11.4 TypeScript11.4.1 TypeScript介绍TypeScript（TS)是微软推出的开源语言 TypeScript是JavaScript的超集（JS有的TS都有） TypeScript &#x3D; Type + JavaScript （在JS基础上增加了类型支持） // JavaScript, 没有明确类型let age = 18//TypeScript，有明确类型，即number 数值类型let age:number = 18
TypeScript 文件扩展名为ts TypeScript可以编译成标准的JavaScript，并且在编译时进行类型检查
安装typescript： npm install -g typescript 查看TS版本: tsc -v 编译TS为JS：tsc hello.ts 运行编译后的TS: node hello.js
11.4.2 TypeScript常用类型 类型标注的位置 标注变量： let msg:string = &quot;hello&quot; 标注参数:
oneMethod(name:string)&#123; console.log(name) &#125;
标注返回值
// 定义m函数，参数为string，返回类型为stringconst m = (name:string):string =&gt;&#123; return &quot;返回类型为String&quot; + name&#125;
字符串、数值、boolean// stringlet uesrname: string = &quot;admin&quot;// number let age: number = 20//booleanlet isTrue: boolean = trueconsole.log(uesrname)console.log(age)console.log(isTrue)
字面量类型function printText(greet:string, name:&quot;tom&quot;| &quot;lily&quot;| &quot;fei&quot; | &quot;jerry&quot;):string &#123; return greet + &quot; : &quot; + name&#125;console.log(printText(&quot;hello&quot; ,&quot;tom&quot;))
interface类型（类似于结构体)interface Cat &#123; name: string, age: number&#125;const cat1:Cat = &#123;name: &quot;小白&quot;, age: 3&#125;
在interface中定义属性时，可以使用?标注可选的属性 interface Cat &#123; name: string, age?: number // 表示属性赋值时，age属性可有可无&#125;
class类 一般用法
class User &#123; name: string; // 属性 constructor(name: string)&#123; // 构造方法 this.name = name; &#125; study() &#123; // 普通方法 console.log(&#x27;[$&#123;this.name&#125;]正在学习&#x27;) &#125;&#125;const u = new User(&quot;Tom&quot;)console.log(u.name)u.study()
实现接口
interface Animal&#123; name: string, eat(): void&#125;class Bird implements Animal&#123; name: string constructor(name: string)&#123; this.name = name &#125; eat(): void &#123; console.log(this.name + &quot;eat bug&quot;) &#125;&#125;const b = new Bird(&quot;鹦鹉&quot;)b.eat();
类的继承
class Parrot extends Bird&#123; say():void &#123; console.log(&quot;我是鹦鹉:&quot; + this.name) &#125;&#125;const p = new Parrot(&quot;小小鹦&quot;)p.eat();p.say();
