1. Spring Security快速入门 Filter是由Servlet容器加上FilterChain进行管理的，然后SpringSecurity是通过在FilterChain中注册一个Filter的代理对象，然后，再到Spring容器中定义SpringSecurity的FilterChain, 这些spring容器中的FilterChain是通过再Servlet中定义的Filter代理对象进行管理的。 1.1 DefaultSecurityFilterChainSpringSecurity默认的SecurityFilterChain 1.2 SecurityProperties定义默认配置 2. Spring Security自定义配置2.1 创建自定义配置UserDetailsService 用来管理用户信息, InMemoryUserDetailManager是UserDetailsService的一个实现，用来管理内存的用户信息。 @Configuration // 配置类//@EnableWebSecurity // 开启Spring Security 的自定义配置（Spring Boot项目中，此注解可以省略public class SecurityConfig &#123; @Bean public UserDetailsService userDetailsService() &#123; //创建基于内存的用户信息管理器 InMemoryUserDetailsManager manager = new InMemoryUserDetailsManager(); //创建UserDetails对象，用于管理用户名、用户密码、用户角色、用户权限的内容 manager.createUser(User.withDefaultPasswordEncoder().username(&quot;user&quot;).password(&quot;password&quot;).roles(&quot;USER&quot;).build()); return manager; &#125;&#125;
基于内存的用户认证流程
程序启动时 创建InMemoryUserDetailsManager对象 创建User对象，封装用户名和密码 使用InMemoryUserDetailsManager将User对象存入内存
校验用户时 SpringSecurity自动使用InMemoryUserDetailsManager的loadUserByUserName方法从内存中获取User对象 在UsernamePasswordAuthenticationFilter过滤器中的attemptAuthentication方法中将用户输入的用户密码和从内存中获取到的用户信息进行比较，进行用户认证
2.2 基于数据库数据源的用户认证 程序启动时 创建DBUserDetailsManager对象, 实现 UserDetailsManager, UserDetailsPasswordService
校验用户时 SpringSecurity自动使用DBUserDetailsManager的loadUserByUserName方法从数据库中获取User对象 在UsernamePasswordAuthenticationFilter过滤器中的attemptAuthentication方法中将用户输入的用户密码和从数据库中获取到的用户信息进行比较，进行用户认证
@Componentpublic class DBUserDetailsManager implements UserDetailsManager, UserDetailsPasswordService &#123; @Resource private UserDao userDao; @Override public UserDetails updatePassword(UserDetails user, String newPassword) &#123; return null; &#125; /** * 插入用户 * @param user */ @Override public void createUser(UserDetails user) &#123; User newUser = new User(); newUser.setUsername(user.getUsername()); newUser.setPassword(user.getPassword()); newUser.setEnabled(true); userDao.insert(newUser); &#125; @Override public void updateUser(UserDetails user) &#123; &#125; @Override public void deleteUser(String username) &#123; &#125; @Override public void changePassword(String oldPassword, String newPassword) &#123; &#125; @Override public boolean userExists(String username) &#123; return false; &#125; /** * * @param username * @return * @throws UsernameNotFoundException */ @Override public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException &#123; QueryWrapper&lt;User&gt; userQueryWrapper = new QueryWrapper&lt;&gt;(); userQueryWrapper.eq(&quot;username&quot;,username); User user = userDao.selectOne(userQueryWrapper); if(user == null) &#123; throw new UsernameNotFoundException(username); &#125;else &#123; Collection&lt;GrantedAuthority&gt; grantedAuthorities = new ArrayList&lt;&gt;(); return new org.springframework.security.core.userdetails.User( user.getUsername(), user.getPassword(), user.getEnabled(), true, true, true, grantedAuthorities); &#125; &#125;&#125;
3. 前后端分离3.2 跨域问题解决需要对开启一些接口的跨域访问 通过实现 WebMvcConfigurer接口统一配置，避免在每个Controller重复注解 @Configurationpublic class CorsConfig implements WebMvcConfigurer &#123; @Override public void addCorsMappings(CorsRegistry registry) &#123; registry.addMapping(&quot;/api/**&quot;) // 指定接口路径 .allowedOrigins(&quot;https://prod.example.com&quot;) // 仅允许此域名跨域，生产环境禁用通配符* .allowedMethods(&quot;GET&quot;, &quot;POST&quot;, &quot;PUT&quot;) // 按需开放方法 .allowedHeaders(&quot;Content-Type&quot;, &quot;Authorization&quot;) .allowCredentials(true) // 允许携带Cookie .maxAge(3600); // 预检请求缓存时间 &#125;&#125;
4. 身份认证5. 授权6. OAuth2
